inputs.manifest:
{
  "schema_version": "1.0.0",
  "id": "flux2-klein/inpaint",
  "label": {
    "en": "Inpaint",
    "ru": "Inpaint"
  },
  "family": "flux2-klein",
  "family_label": "Flux 2 Klein",
  "mode": "inpaint",
  "order": 30,
  "controls": [
    {
      "param": "prompt",
      "kind": "prompt",
      "superprompt": true
    },
    {
      "param": "seed",
      "kind": "seed"
    },
    {
      "param": "replace",
      "kind": "toggle",
      "default": false,
      "label": {
        "en": "Replace (full redraw)",
        "ru": "Replace (полная перерисовка)"
      },
      "tooltip": {
        "en": "Regenerate the masked region from scratch; the strength slider is ignored (100%).",
        "ru": "Перерисовать маску с нуля; ползунок силы игнорируется (100%)."
      }
    },
    {
      "param": "denoise",
      "kind": "number",
      "min": 0.1,
      "max": 0.5,
      "step": 0.1,
      "label": {
        "en": "Repaint strength",
        "ru": "Сила перерисовки"
      }
    },
    {
      "param": "loras",
      "kind": "loras",
      "max": 8,
      "strength": [
        -2.0,
        2.0
      ]
    },
    {
      "param": "steps",
      "kind": "number",
      "advanced": true,
      "min": 1,
      "max": 60,
      "label": {
        "en": "Steps",
        "ru": "Шаги"
      }
    },
    {
      "param": "cfg",
      "kind": "number",
      "advanced": true,
      "min": 0,
      "max": 15,
      "step": 0.1,
      "label": {
        "en": "CFG",
        "ru": "CFG"
      }
    }
  ],
  "refs": {
    "max": 0
  },
  "requires": [
    "source_image",
    "mask"
  ],
  "inpaint_params": {
    "image": "source_image",
    "mask": "mask"
  },
  "negative_prompt": false,
  "models": [
    {
      "title": "studio:model",
      "input": "unet_name",
      "folder": "diffusion_models",
      "match": "flux.?2.?klein.*(9b|4b)|ArtiusFlux"
    },
    {
      "title": "studio:clip",
      "input": "clip_name",
      "folder": "text_encoders",
      "match": "qwen_3_(8b|4b)"
    },
    {
      "title": "studio:vae",
      "input": "vae_name",
      "folder": "vae",
      "match": "flux2-vae"
    }
  ],
  "literals": {
    "replace": {
      "node": "smart",
      "input": "replace"
    }
  }
}
